// This code has been fully generated by an AI.

// Package health imports daily health values (resting heart rate, HRV,
// sleep, Body Battery, stress, steps, SpO2, respiration, weight, VO2max,
// fitness age) and Garmin's training metrics (readiness, training status,
// acute/chronic load) from the JSON files of the Garmin data export.
//
// The export is a ZIP whose DI_CONNECT folders hold one JSON array per file
// and period. Values are merged per local date, so files complement each
// other and importing the same export again changes nothing.
package health

import (
	"archive/zip"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"math"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/stefanluchs/my-velo/internal/store"
)

// Stats summarizes an import.
type Stats struct {
	Files int // JSON files read
	Days  int // dates with at least one value
}

// maxJSONSize guards against unexpected huge entries.
const maxJSONSize = 64 << 20

// kind is a parser for one export file type; order matters where two
// kinds fill the same column (later wins).
type kind struct {
	pattern *regexp.Regexp
	parse   func(data []byte, days days) error
}

var kinds = []kind{
	{regexp.MustCompile(`DI-Connect-Aggregator/UDSFile_[^/]*\.json$`), parseUDS},
	{regexp.MustCompile(`DI-Connect-Wellness/[^/]*_sleepData\.json$`), parseSleep},
	{regexp.MustCompile(`DI-Connect-Wellness/[^/]*_healthStatusData\.json$`), parseHealthStatus},
	{regexp.MustCompile(`DI-Connect-Wellness/[^/]*_userBioMetrics\.json$`), parseBioMetrics},
	{regexp.MustCompile(`DI-Connect-Wellness/[^/]*_fitnessAgeData\.json$`), parseFitnessAge},
	{regexp.MustCompile(`DI-Connect-Metrics/MetricsMaxMetData_[^/]*\.json$`), parseMaxMet},
	{regexp.MustCompile(`DI-Connect-Metrics/TrainingReadinessDTO_[^/]*\.json$`), parseReadiness},
	{regexp.MustCompile(`DI-Connect-Metrics/TrainingHistory_[^/]*\.json$`), parseTrainingHistory},
	{regexp.MustCompile(`DI-Connect-Metrics/MetricsAcuteTrainingLoad_[^/]*\.json$`), parseAcuteLoad},
}

// days collects values per date during an import.
type days map[string]store.HealthValues

func (d days) set(date, col string, v any) {
	if len(date) < 10 {
		return
	}
	date = date[:10]
	if _, err := time.Parse(time.DateOnly, date); err != nil {
		return
	}
	if d[date] == nil {
		d[date] = store.HealthValues{}
	}
	d[date][col] = v
}

// ImportPath imports the health files of every ZIP file at or below root.
// ZIPs without health files are ignored, so the FIT import folder can be
// passed as is.
func ImportPath(ctx context.Context, st *store.Store, root string) (Stats, error) {
	var total Stats
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() || !strings.EqualFold(filepath.Ext(path), ".zip") {
			return nil
		}
		s, err := ImportZip(ctx, st, path)
		if err != nil {
			return fmt.Errorf("%s: %w", filepath.Base(path), err)
		}
		total.Files += s.Files
		total.Days += s.Days
		return nil
	})
	return total, err
}

// ImportZip imports the health files of one Garmin export ZIP.
func ImportZip(ctx context.Context, st *store.Store, path string) (Stats, error) {
	zr, err := zip.OpenReader(path)
	if err != nil {
		return Stats{}, err
	}
	defer zr.Close()
	collected := days{}
	var stats Stats
	for _, k := range kinds {
		for _, f := range zr.File {
			if !k.pattern.MatchString(f.Name) {
				continue
			}
			if err := ctx.Err(); err != nil {
				return stats, err
			}
			data, err := readEntry(f)
			if err != nil {
				return stats, fmt.Errorf("%s: %w", f.Name, err)
			}
			if err := k.parse(data, collected); err != nil {
				return stats, fmt.Errorf("%s: %w", f.Name, err)
			}
			stats.Files++
		}
	}
	dates := make([]string, 0, len(collected))
	for d := range collected {
		dates = append(dates, d)
	}
	sort.Strings(dates)
	for _, d := range dates {
		if err := st.UpsertHealth(ctx, d, collected[d]); err != nil {
			return stats, err
		}
	}
	stats.Days = len(dates)
	return stats, nil
}

func readEntry(f *zip.File) ([]byte, error) {
	rc, err := f.Open()
	if err != nil {
		return nil, err
	}
	defer rc.Close()
	data, err := io.ReadAll(io.LimitReader(rc, maxJSONSize+1))
	if err != nil {
		return nil, err
	}
	if len(data) > maxJSONSize {
		return nil, fmt.Errorf("larger than %d bytes", maxJSONSize)
	}
	return data, nil
}

// positive returns v if it is a real measurement; Garmin uses negative
// values (-1, -2) for "no data".
func positive(v *float64) (float64, bool) {
	if v == nil || *v <= 0 || math.IsNaN(*v) {
		return 0, false
	}
	return *v, true
}

func setInt(d days, date, col string, v *float64) {
	if x, ok := positive(v); ok {
		d.set(date, col, int(math.Round(x)))
	}
}

func setFloat(d days, date, col string, v *float64, decimals int) {
	if x, ok := positive(v); ok {
		p := math.Pow(10, float64(decimals))
		d.set(date, col, math.Round(x*p)/p)
	}
}

func parseUDS(data []byte, d days) error {
	var recs []struct {
		CalendarDate     string   `json:"calendarDate"`
		RestingHeartRate *float64 `json:"restingHeartRate"`
		MinHeartRate     *float64 `json:"minHeartRate"`
		MaxHeartRate     *float64 `json:"maxHeartRate"`
		TotalSteps       *float64 `json:"totalSteps"`
		ModerateMinutes  *float64 `json:"moderateIntensityMinutes"`
		VigorousMinutes  *float64 `json:"vigorousIntensityMinutes"`
		AverageSpo2Value *float64 `json:"averageSpo2Value"`
		LowestSpo2Value  *float64 `json:"lowestSpo2Value"`
		Respiration      *struct {
			AvgWaking *float64 `json:"avgWakingRespirationValue"`
		} `json:"respiration"`
		BodyBattery *struct {
			Charged *float64 `json:"chargedValue"`
			Drained *float64 `json:"drainedValue"`
			Stats   []struct {
				Type  string   `json:"bodyBatteryStatType"`
				Value *float64 `json:"statsValue"`
			} `json:"bodyBatteryStatList"`
		} `json:"bodyBattery"`
		AllDayStress *struct {
			Aggregators []struct {
				Type    string   `json:"type"`
				Average *float64 `json:"averageStressLevel"`
				Max     *float64 `json:"maxStressLevel"`
			} `json:"aggregatorList"`
		} `json:"allDayStress"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	for _, r := range recs {
		date := r.CalendarDate
		setInt(d, date, "resting_hr", r.RestingHeartRate)
		setInt(d, date, "min_hr", r.MinHeartRate)
		setInt(d, date, "max_hr", r.MaxHeartRate)
		setInt(d, date, "steps", r.TotalSteps)
		if r.ModerateMinutes != nil && *r.ModerateMinutes >= 0 {
			d.set(date, "intensity_moderate_min", int(*r.ModerateMinutes))
		}
		if r.VigorousMinutes != nil && *r.VigorousMinutes >= 0 {
			d.set(date, "intensity_vigorous_min", int(*r.VigorousMinutes))
		}
		setFloat(d, date, "spo2_avg", r.AverageSpo2Value, 1)
		setInt(d, date, "spo2_low", r.LowestSpo2Value)
		if r.Respiration != nil {
			setFloat(d, date, "respiration_avg", r.Respiration.AvgWaking, 1)
		}
		if bb := r.BodyBattery; bb != nil {
			setInt(d, date, "body_battery_charged", bb.Charged)
			setInt(d, date, "body_battery_drained", bb.Drained)
			for _, s := range bb.Stats {
				switch s.Type {
				case "HIGHEST":
					setInt(d, date, "body_battery_high", s.Value)
				case "LOWEST":
					setInt(d, date, "body_battery_low", s.Value)
				}
			}
		}
		if st := r.AllDayStress; st != nil {
			for _, a := range st.Aggregators {
				if a.Type == "TOTAL" {
					setInt(d, date, "stress_avg", a.Average)
					setInt(d, date, "stress_max", a.Max)
				}
			}
		}
	}
	return nil
}

func parseSleep(data []byte, d days) error {
	var recs []struct {
		CalendarDate string   `json:"calendarDate"`
		Deep         *float64 `json:"deepSleepSeconds"`
		Light        *float64 `json:"lightSleepSeconds"`
		REM          *float64 `json:"remSleepSeconds"`
		Awake        *float64 `json:"awakeSleepSeconds"`
		Scores       *struct {
			Overall *float64 `json:"overallScore"`
		} `json:"sleepScores"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	for _, r := range recs {
		if r.CalendarDate == "" {
			continue // retro entries without a night
		}
		total := 0.0
		for _, v := range []*float64{r.Deep, r.Light, r.REM} {
			if x, ok := positive(v); ok {
				total += x
			}
		}
		if total == 0 {
			continue
		}
		d.set(r.CalendarDate, "sleep_s", int(total))
		setInt(d, r.CalendarDate, "sleep_deep_s", r.Deep)
		setInt(d, r.CalendarDate, "sleep_light_s", r.Light)
		setInt(d, r.CalendarDate, "sleep_rem_s", r.REM)
		if r.Awake != nil && *r.Awake >= 0 {
			d.set(r.CalendarDate, "sleep_awake_s", int(*r.Awake))
		}
		if r.Scores != nil {
			setInt(d, r.CalendarDate, "sleep_score", r.Scores.Overall)
		}
	}
	return nil
}

func parseHealthStatus(data []byte, d days) error {
	var recs []struct {
		CalendarDate string `json:"calendarDate"`
		Metrics      []struct {
			Type   string   `json:"type"`
			Value  *float64 `json:"value"`
			Low    *float64 `json:"baselineLowerLimit"`
			High   *float64 `json:"baselineUpperLimit"`
			Status string   `json:"status"`
		} `json:"metrics"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	for _, r := range recs {
		for _, m := range r.Metrics {
			if m.Type != "HRV" {
				continue
			}
			setFloat(d, r.CalendarDate, "hrv_night_avg", m.Value, 1)
			setFloat(d, r.CalendarDate, "hrv_baseline_low", m.Low, 1)
			setFloat(d, r.CalendarDate, "hrv_baseline_high", m.High, 1)
			if m.Status != "" {
				d.set(r.CalendarDate, "hrv_status", m.Status)
			}
		}
	}
	return nil
}

func parseBioMetrics(data []byte, d days) error {
	var recs []struct {
		Meta struct {
			CalendarDate string `json:"calendarDate"`
		} `json:"metaData"`
		Weight *struct {
			Grams *float64 `json:"weight"`
		} `json:"weight"`
		VO2Running *float64 `json:"vo2MaxRunning"`
		VO2Cycling *float64 `json:"vo2MaxCycling"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	for _, r := range recs {
		date := r.Meta.CalendarDate
		if r.Weight != nil {
			if g, ok := positive(r.Weight.Grams); ok {
				d.set(date, "weight_kg", math.Round(g/100)/10)
			}
		}
		setFloat(d, date, "vo2max_running", r.VO2Running, 1)
		setFloat(d, date, "vo2max_cycling", r.VO2Cycling, 1)
	}
	return nil
}

func parseFitnessAge(data []byte, d days) error {
	var recs []struct {
		AsOf string   `json:"asOfDateGmt"`
		Age  *float64 `json:"currentBioAge"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	for _, r := range recs {
		setFloat(d, r.AsOf, "fitness_age", r.Age, 1)
	}
	return nil
}

func parseMaxMet(data []byte, d days) error {
	var recs []struct {
		CalendarDate string   `json:"calendarDate"`
		Sport        string   `json:"sport"`
		VO2Max       *float64 `json:"vo2MaxValue"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	for _, r := range recs {
		col := "vo2max_running"
		if r.Sport == "CYCLING" {
			col = "vo2max_cycling"
		}
		setFloat(d, r.CalendarDate, col, r.VO2Max, 1)
	}
	return nil
}

// parseReadiness keeps one readiness per day: the morning value
// (AFTER_WAKEUP_RESET) if present, otherwise the latest.
func parseReadiness(data []byte, d days) error {
	var recs []struct {
		CalendarDate string   `json:"calendarDate"`
		Timestamp    string   `json:"timestamp"`
		Context      string   `json:"inputContext"`
		Score        *float64 `json:"score"`
		Level        string   `json:"level"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	type pick struct {
		morning bool
		ts      string
		score   *float64
		level   string
	}
	best := map[string]pick{}
	for _, r := range recs {
		if r.Score == nil {
			continue
		}
		p := pick{morning: r.Context == "AFTER_WAKEUP_RESET", ts: r.Timestamp, score: r.Score, level: r.Level}
		cur, ok := best[r.CalendarDate]
		if !ok || (p.morning && !cur.morning) || (p.morning == cur.morning && p.ts > cur.ts) {
			best[r.CalendarDate] = p
		}
	}
	for date, p := range best {
		if *p.score >= 0 {
			d.set(date, "readiness_score", int(math.Round(*p.score)))
		}
		if p.level != "" {
			d.set(date, "readiness_level", p.level)
		}
	}
	return nil
}

// parseTrainingHistory keeps the latest training status per day (Garmin
// writes one per device and sport).
func parseTrainingHistory(data []byte, d days) error {
	var recs []struct {
		CalendarDate string `json:"calendarDate"`
		Timestamp    string `json:"timestamp"`
		Status       string `json:"trainingStatus"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	latest := map[string][2]string{}
	for _, r := range recs {
		if r.Status == "" {
			continue
		}
		if cur, ok := latest[r.CalendarDate]; !ok || r.Timestamp > cur[0] {
			latest[r.CalendarDate] = [2]string{r.Timestamp, r.Status}
		}
	}
	for date, v := range latest {
		d.set(date, "training_status", v[1])
	}
	return nil
}

func parseAcuteLoad(data []byte, d days) error {
	var recs []struct {
		CalendarDate json.Number `json:"calendarDate"`
		Acute        *float64    `json:"dailyTrainingLoadAcute"`
		Chronic      *float64    `json:"dailyTrainingLoadChronic"`
	}
	if err := json.Unmarshal(data, &recs); err != nil {
		return err
	}
	for _, r := range recs {
		// calendarDate is milliseconds since the epoch at 00:00 UTC of the day.
		ms, err := r.CalendarDate.Int64()
		if err != nil {
			continue
		}
		date := time.UnixMilli(ms).UTC().Format(time.DateOnly)
		setFloat(d, date, "garmin_acute_load", r.Acute, 0)
		setFloat(d, date, "garmin_chronic_load", r.Chronic, 0)
	}
	return nil
}
